import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './Dashboard.css';

export default function Dashboard({company,leads,employees,attendance,overdue,properties,setPage,money}) { const won=leads.filter(l=>l.status==='Won').length; const hot=leads.filter(l=>['Hot','Negotiation'].includes(l.status)).length; const conversion=leads.length?Math.round(won/leads.length*100):0; return <div className="module-page module-page--dashboard"><div className="page-heading"><div><div className="eyebrow">MONDAY, OCTOBER 26, 2026 <span className="live-dot"/></div><h1>Good morning, <span>Team.</span> <span className="wave">✦</span></h1><p>Here's what's happening with your business today.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>setPage('Reports')}>↗ View reports</button><button className="btn primary" onClick={()=>setPage('Leads')}>＋ New lead</button></div></div><div className="hero-banner"><div className="hero-banner-copy"><span className="banner-tag">✦ YOUR BUSINESS AT A GLANCE</span><h2>Make every opportunity<br/>count.</h2><p>Stay ahead of follow-ups, empower your team, and turn more enquiries into successful deals.</p><button onClick={()=>setPage('Leads')}>Explore your pipeline <span>→</span></button></div><div className="hero-visual"><div className="visual-ring ring-a"/><div className="visual-ring ring-b"/><div className="visual-center">E<span>+</span></div><div className="visual-stat stat-a"><small>Open leads</small><b>{leads.filter(l=>!['Won','Lost'].includes(l.status)).length}</b><span>↗ Active pipeline</span></div><div className="visual-stat stat-b"><small>Properties</small><b>{properties.length}</b><span>▧ In inventory</span></div></div><div className="banner-orb orb-a"/><div className="banner-orb orb-b"/></div><div className="stats-grid"><Stat label="Total leads" value={leads.length} change="Live pipeline" icon="♧" tone="purple" foot={`${hot} hot / negotiation`} /><Stat label="Follow-ups due" value={overdue.length} change="Needs attention" icon="◷" tone="orange" foot="Prioritise today's calls"/><Stat label="Team members" value={employees.length} change="Active roster" icon="♙" tone="blue" foot={`${attendance.length} attendance records today`}/><Stat label="Lead conversion" value={`${conversion}%`} change="Won / total leads" icon="↗" tone="green" foot={`${won} won deals recorded`}/></div><div className="dashboard-grid"><section className="panel pipeline-panel"><div className="panel-head"><div><h3>Lead pipeline</h3><p>Track opportunities across every stage</p></div><button className="text-action" onClick={()=>setPage('Leads')}>View all →</button></div><div className="pipeline-bars">{[['New',leads.filter(l=>l.status==='New').length,'#8b83ff'],['Qualified',leads.filter(l=>l.status==='Qualified').length,'#5f8cf7'],['Hot',leads.filter(l=>l.status==='Hot').length,'#e7a14b'],['Site Visit',leads.filter(l=>l.status==='Site Visit').length,'#26b7a4'],['Negotiation',leads.filter(l=>l.status==='Negotiation').length,'#d57ac5'],['Won',won,'#39b985']].map(([label,count,color])=><div className="pipeline-row" key={label}><span>{label}</span><div className="bar-track"><div className="bar-fill" style={{width:`${Math.max(4,count/Math.max(leads.length,1)*100)}%`,background:color}}/></div><b>{count}</b></div>)}</div><div className="panel-bottom-note"><span className="note-icon">✦</span><span><b>{hot} high-intent leads</b> are in Hot or Negotiation. Keep momentum with a timely follow-up.</span></div></section><section className="panel tasks-panel"><div className="panel-head"><div><h3>Priority follow-ups</h3><p>Leads that need your attention</p></div><button className="text-action" onClick={()=>setPage('Follow-ups')}>See schedule →</button></div><div className="task-list">{overdue.slice(0,4).map((l,i)=><div className="task-row" key={l.id}><div className={`task-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div className="task-info"><b>{l.name}</b><small>{l.location||'Location not added'} · {l.assigned}</small></div><span className={`status-pill ${l.next==='Today'?'warning':'neutral'}`}>{l.next}</span></div>)}{!overdue.length&&<Empty title="You're all caught up" desc="No priority follow-ups at the moment."/>}</div><button className="full-action" onClick={()=>setPage('Follow-ups')}>Open follow-up manager <span>→</span></button></section></div><div className="dashboard-grid lower-grid"><section className="panel activity-panel"><div className="panel-head"><div><h3>Recent opportunities</h3><p>Latest lead activity in your workspace</p></div><button className="text-action" onClick={()=>setPage('Leads')}>All leads →</button></div><div className="table-wrap"><table><thead><tr><th>CONTACT</th><th>INTEREST</th><th>OWNER</th><th>STATUS</th><th>BUDGET</th></tr></thead><tbody>{leads.slice(0,5).map((l,i)=><tr key={l.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div><b>{l.name}</b><small>{l.id}</small></div></div></td><td>{l.type||'—'}<small className="cell-sub">{l.location}</small></td><td>{l.assigned||'Unassigned'}</td><td><Status value={l.status}/></td><td>{money(l.budget)}</td></tr>)}</tbody></table></div></section><section className="panel team-panel"><div className="panel-head"><div><h3>Team snapshot</h3><p>Who's on your roster</p></div><button className="text-action" onClick={()=>setPage('Employees')}>Manage →</button></div>{employees.slice(0,4).map((e,i)=><div className="team-row" key={e.id}><div className={`team-avatar av-${i%4}`}>{e.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div className="team-person"><b>{e.name}</b><small>{e.role}</small></div><span className={`online-state ${e.status==='Active'?'online':'offline'}`}>{e.status}</span></div>)}<div className="team-footer"><div className="mini-stack">{employees.slice(0,4).map((e,i)=><span className={`team-avatar av-${i%4}`} key={e.id}>{e.name[0]}</span>)}</div><span>{employees.length} team members in this workspace</span></div></section></div></div>; }
